// X20: independently variable 20/48 decimal coefficient bands.
// g++ -O3 -std=c++17 two_counter.cpp -o /tmp/x20 && /tmp/x20
#include <bits/stdc++.h>
using namespace std;using V=vector<uint8_t>;using U=uint64_t;
const V B={17,5,0,1,13,4,14,12,9,8,15,16,17,13,17,9,1,4,4,11,8,16,0,9,14,11,9,11,6,13,18,9,4,7,17,15,9,7,13};
const V W={17,3,1,13,17,11,14,3,18,1,2,0,7,3,14,12,15,9,7,13};
const V Q={4,4,14,1,5,11,7,1,15,12,7,9,9,12,14,4,0,6,5,17,13,9,7,3,13,10,4,13,5,1,9,4,11,6,16,3,7,7,12,4,2,13,2,15,10,10,9,3};
V seed(int m,int n){V h=B;for(int j=0;j<m;j++)h.insert(h.end(),W.begin(),W.end());h.push_back(9);for(int j=0;j<n;j++)h.insert(h.end(),Q.begin(),Q.end());V p=h;p.push_back(9);p.insert(p.end(),h.rbegin(),h.rend());return p;}
pair<V,int> norm(const V&p){V d;int c=0;for(int x:p){int s=x+c;d.push_back(s%10);c=s/10;}if(c)d.push_back(c);return {d,c};}
V add(const V&d){V o;int c=0;int n=d.size();for(int i=0;i<n;i++){int s=d[i]+d[n-1-i]+c;o.push_back(s%10);c=s/10;}if(c)o.push_back(c);return o;}
V pairs(const V&d){V p(d.size());for(int i=0;i<(int)d.size();i++)p[i]=d[i]+d[d.size()-1-i];return p;}
V fcarry(V p){for(int c0=0;c0<=1;c0++){int c=c0;V o;for(int x:p){int s=x+c;o.push_back(s%10);c=s/10;}if(c==c0)return o;}throw runtime_error("no fixed carry");}
V bulk(V w,int g){V l=fcarry(w),r=w;reverse(r.begin(),r.end());auto h=fcarry(r);reverse(h.begin(),h.end());V v(w.size());for(int i=0;i<(int)v.size();i++)v[i]=l[i]+h[(i-g+(int)v.size())%v.size()];return v;}
bool ispal(const V&d){for(size_t i=0;i<d.size()/2;i++)if(d[i]!=d[d.size()-1-i])return false;return true;}
struct Bits{U lo=0,hi=0;void add(int j){if(j<64)lo|=(1ULL<<j);else hi|=(1ULL<<(j-64));}bool has(int j)const{return j<64?(lo>>j)&1:(hi>>(j-64))&1;}void absorb(Bits b){lo|=b.lo;hi|=b.hi;}bool operator==(const Bits&b)const{return lo==b.lo&&hi==b.hi;}};
struct Mat{array<Bits,80> row;bool operator==(const Mat&b)const{return row==b.row;}};
Mat ident(){Mat m;for(int i=0;i<80;i++)m.row[i].add(i);return m;}
Mat mul(const Mat&a,const Mat&b){Mat c;for(int i=0;i<80;i++){U x=a.row[i].lo,y=a.row[i].hi;while(x){int j=__builtin_ctzll(x);c.row[i].absorb(b.row[j]);x&=x-1;}while(y){int j=64+__builtin_ctzll(y);c.row[i].absorb(b.row[j]);y&=y-1;}}return c;}
int id(int a,int h,int z,int e){return ((a*2+h)*10+z)*2+e;}
const auto& syms(){static array<array<array<Mat,19>,19>,2> cache=[](){array<array<array<Mat,19>,19>,2> r{};for(int g=0;g<2;g++)for(int x=0;x<19;x++)for(int y=0;y<19;y++)for(int a=0;a<2;a++)for(int h=0;h<2;h++)for(int z=0;z<10;z++)for(int e=0;e<2;e++)for(int inner=0;inner<2;inner++){int dl=(x+a)%10,dh=(x+inner)%10,u=g?z:dh;if((x+inner)/10!=h||y!=dl+u)continue;r[g][x][y].row[id(a,h,z,e)].add(id((x+a)/10,inner,dh,e||(dl!=u)));}return r;}();return cache;}
Mat word(const V&a,const V&b,int g){if(a.size()!=b.size())throw runtime_error("word sizes");Mat M=ident();for(size_t i=0;i<a.size();i++)M=mul(M,syms()[g][a[i]][b[i]]);return M;}
bool accept(const Mat&M,int g,int center,int outcenter){auto bits=M.row[id(0,g,g,0)];for(int i=0;i<80;i++)if(bits.has(i)){int a=i/40,h=(i/20)%2,z=(i/2)%10,e=i%2;if(center<0){if(a!=h||outcenter!=(g?2*z:-1))continue;}else{int d=(center+a)%10;if((center+a)/10!=h||outcenter!=(g?d+z:2*d))continue;if(g&&d!=z)e=1;}if(e)return true;}return false;}
struct State{V A,W,J,Q,C;int center=-1;bool operator==(const State&b)const{return A==b.A&&W==b.W&&J==b.J&&Q==b.Q&&C==b.C&&center==b.center;}};
State extract(const V&p,int m,int n,const V&w,const V&q){int a=199,b=20*m-601,c=20*m+616,d=20*m+48*n-1304,h=p.size()/2;if(m<40||n<40||a>b||b>c||c>d||d>h)throw runtime_error("cut order");for(int j=a;j<b;j++)if(p[j]!=w[(j-a)%20])throw runtime_error("W lost");for(int j=c;j<d;j++)if(p[j]!=q[(j-c)%48])throw runtime_error("Q lost");auto take=[&](int l,int r){return V(p.begin()+l,p.begin()+r);};return {take(0,a),w,take(b,c),q,take(d,h),p.size()%2?int(p[h]):-1};}
bool edge(const State&s,const State&u,int g){if(s.A.size()!=u.A.size()||s.J.size()!=u.J.size())throw runtime_error("literal geometry");Mat M0=word(s.A,u.A,g),MW=word(s.W,u.W,g),MJ=word(s.J,u.J,g),MQ=word(s.Q,u.Q,g);V target;int last;if(s.C.size()==u.C.size()){target=u.C;last=u.center;}else if(s.C.size()+1==u.C.size()&&s.center>=0&&u.center<0){target=u.C;last=target.back();target.pop_back();}else throw runtime_error("centre geometry");Mat MC=word(s.C,target,g);if(!(mul(MW,MW)==MW)||!(mul(MQ,MQ)==MQ))throw runtime_error("no idempotence");for(int r=0;r<2;r++)for(int v=0;v<2;v++){Mat X=M0;if(r)X=mul(X,MW);X=mul(X,MJ);if(v)X=mul(X,MQ);X=mul(X,MC);if(!accept(X,g,s.center,last))return false;}return true;}
int main(int argc,char**argv){try{int maxsteps=argc>1?stoi(argv[1]):480;vector<pair<int,int>> cases={{40,40},{41,40},{40,41},{41,41},{52,67}};vector<V> p,d;for(auto [m,n]:cases){p.push_back(seed(m,n));d.push_back(norm(p.back()).first);}V w=W,q=Q;State old,initial;for(int t=0;t<=maxsteps;t++){State s=extract(p[0],40,40,w,q);if(t==0)initial=s;for(int i=1;i<(int)cases.size();i++)if(!(extract(p[i],cases[i].first,cases[i].second,w,q)==s))throw runtime_error("asymmetric factorization failure t="+to_string(t)+" case="+to_string(i));if(t && !edge(old,s,(t-1)%2==0))throw runtime_error("four-corner transfer failure t="+to_string(t-1));for(int i=0;i<(int)cases.size();i++){if(ispal(d[i])||norm(p[i]).first!=d[i]||norm(p[i]).second!=(t%2==0))throw runtime_error("arith fail t="+to_string(t));}if(t==maxsteps){cout<<"PASS independent counters m,n>=40 up to "<<maxsteps<<" edges (4 corner matrices per edge; all 5 direct integer controls), C0="<<1344<<", Cend="<<s.C.size()<<", Jchanged="<<inner_product(s.J.begin(),s.J.end(),initial.J.begin(),0,plus<int>(),not_equal_to<>())<<"\n";return 0;}old=move(s);for(int i=0;i<(int)cases.size();i++){V nd=add(d[i]), np=pairs(d[i]);d[i].swap(nd);p[i].swap(np);}w=bulk(w,t%2==0);q=bulk(q,t%2==0);if((t+1)%80==0)cerr<<"X20 checked "<<t+1<<" edges\n";}}
catch(const exception&e){cerr<<"FAIL "<<e.what()<<"\n";return 2;}return 2;}
